import React from 'react';
import './AQIInputForm.css';

const AQIInputForm = ({ features, setFeatures, setResult }) => {
  const handleChange = (e) => {
    setFeatures({ ...features, [e.target.name]: parseFloat(e.target.value) });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const res = await fetch('http://localhost:5000/predict', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(features),
    });
    const data = await res.json();
    setResult(data);
  };

  return (
    <form className="aqi-input-form" onSubmit={handleSubmit}>
      <h3>📊 Predict Indoorss AQI</h3>
      {[
        ['PM2.5', 'PM2_5'],
        ['CO', 'CO'],
        ['NO2', 'NO2'],
        ['NH3', 'NH3'],
        ['O3', 'O3'],
        ['Temp (°C)', 'Temp'],
        ['Humidity (%)', 'Humidity'],
        ['Pressure (hPa)', 'Pressure'],
      ].map(([label, name]) => (
        <div key={name} className="input-group">
          <label>{label}</label>
          <input
            type="number"
            name={name}
            value={features[name]}
            onChange={handleChange}
            step="0.1"
            required
          />
        </div>
      ))}
      <button type="submit">Predict</button>
    </form>
  );
};

export default AQIInputForm;
